<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import QRCode from 'qrcode';
import { MAPS } from './config.js';
const props=defineProps({room:Object,invite:Object,status:Object,busy:Boolean,error:String});
const emit=defineEmits(['command','invite','leave']);
const now=ref(Date.now()/1000),qr=ref(''),copied=ref(false),serverOffset=ref(0);
watch(()=>props.room.server_time,value=>{serverOffset.value=value-Date.now()/1000;},{immediate:true});
const interval=setInterval(()=>{now.value=Date.now()/1000;},250);onBeforeUnmount(()=>clearInterval(interval));
const me=computed(()=>props.room.players[props.room.self]);
const host=computed(()=>props.room.self===props.room.host);
const players=computed(()=>Object.values(props.room.players));
const canStart=computed(()=>players.value.length===2&&players.value.every(p=>p.ready&&p.online)&&props.room.phase==='lobby');
const editable=computed(()=>props.room.phase==='lobby'&&!props.busy);
const map=computed(()=>MAPS.find(m=>m.id===props.room.map)||MAPS[0]);
const remaining=computed(()=>Math.max(0,Math.ceil((props.invite?.expires||0)-now.value)));
const seconds=computed(()=>Math.max(1,Math.ceil(props.room.starts_at-now.value-serverOffset.value)));
const title=computed(()=>({loading:'正在加载战场',countdown:'即将开战',reconnecting:'等待连接恢复',closed:'房间已结束'}[props.room.phase]||'好友对战'));
watch(()=>props.invite?.url,async url=>{qr.value='';if(url)try{const data=await QRCode.toDataURL(url,{width:224,margin:2,errorCorrectionLevel:'M',color:{dark:'#152b33',light:'#fff7e9'}});if(url===props.invite?.url)qr.value=data;}catch{}},{immediate:true});
function command(action,args={}){emit('command',{action,args});}
async function copy(){try{await navigator.clipboard.writeText(props.invite.url);copied.value=true;setTimeout(()=>copied.value=false,1800);}catch{copied.value=false;}}
</script>

<template>
 <section class="room-screen" aria-label="双人对战大厅">
  <div class="room-container">
   <header class="room-header"><div><span class="room-eyebrow">ANKA / FRONTLINE DUEL</span><h1>{{title}}<small>房间 {{room.code}}</small></h1></div><button class="room-quiet" @click="emit('leave')">离开房间 ↗</button></header>
   <div class="room-layout">
    <div class="room-main">
     <div class="room-section"><span>01 / 集结先锋</span><b>{{players.filter(p=>p.online).length}} / 2 在线</b></div>
     <div class="seat-grid">
      <article v-for="(player,index) in players" :key="player.id" class="player-seat" :class="{'seat-guest':player.role==='guest','seat-ready':player.ready}">
       <div class="seat-top"><span>{{player.role==='host'?'P1 / 房主':'P2 / 好友'}}</span><i :class="{online:player.online}"/>{{player.online?'已连接':'连接中'}}</div>
       <div class="seat-avatar" :class="player.character"><span>{{player.character==='female'?'K':'J'}}</span><small>{{player.character==='female'?'RECON':'ASSAULT'}}</small></div>
       <div class="seat-name"><h2>{{player.name}}<small v-if="player.id===room.self">你</small></h2><b :class="{ready:player.ready}">{{player.loaded?'加载完成':player.ready?'已准备':'选择中'}}</b></div>
       <div v-if="player.id===room.self" class="seat-characters" aria-label="选择你的角色"><button v-for="kind in ['male','female']" :key="kind" :aria-pressed="player.character===kind" :class="{selected:player.character===kind}" :disabled="!editable" @click="command('character',{character:kind})">{{kind==='male'?'小杰 · 突击':'小葵 · 侦察'}}</button></div>
       <p v-else class="seat-character-label">{{player.character==='female'?'小葵 / 侦察先锋':'小杰 / 突击先锋'}}</p>
      </article>
      <article v-if="players.length===1" class="player-seat empty-seat"><span class="empty-plus">＋</span><h2>等一位好友</h2><p>扫码或打开邀请链接<br>即可加入，无须注册</p><span class="waiting-dots">● ● ●</span></article>
     </div>
     <div class="room-section"><span>02 / 选择战场</span><b>{{host?'由你选择':'由房主选择'}}</b></div>
     <div class="room-maps"><button v-for="item in MAPS" :key="item.id" :class="{selected:room.map===item.id}" :style="{'--map-accent':item.color}" :disabled="!host||!editable" :aria-pressed="room.map===item.id" @click="command('map',{map:item.id})"><span>{{item.tag.split(' / ')[0]}}</span><strong>{{item.name}}</strong><small>{{room.map===item.id?'已选战场':item.english.split(' ')[0]}}</small></button></div>
     <div class="room-rules"><span>本场规则</span><strong>先得 {{room.rules.target}} 分</strong><i/><strong>{{room.rules.duration/60}} 分钟</strong><i/><span>3 秒复活 · 2 秒保护</span></div>
     <p class="room-notice" role="status">{{room.notice || (room.phase==='lobby'?'选好角色后点击准备。房主修改地图，会取消双方准备。':room.phase==='reconnecting'?'短暂断线保留席位 30 秒；刷新页面后回大厅重新准备。':room.phase==='countdown'?'双方资源已就绪，即将同步开战。':'两位玩家加载完成后自动倒计时。')}}</p>
    </div>
    <aside class="room-aside">
     <div class="room-section"><span>{{players.length===1?'03 / 邀请好友':'03 / 准备上场'}}</span></div>
     <template v-if="host&&players.length===1">
      <div class="qr-frame"><img v-if="qr&&remaining>0" :src="qr" alt="扫码加入这个双人游戏房间"><div v-else class="qr-placeholder">{{remaining===0?'邀请待生成 / 已过期':'正在生成二维码…'}}</div></div>
      <div class="invite-expiry"><span :class="{expired:!remaining}">{{remaining>0?`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')} 内有效`:'生成邀请，等待好友加入'}}</span><button :disabled="busy" @click="emit('invite')">重新生成</button></div>
      <button class="room-copy" :disabled="!invite||!remaining" @click="copy">{{copied?'已复制邀请链接 ✓':'复制邀请链接 ↗'}}</button>
      <input v-if="invite&&remaining" class="invite-link" :value="invite.url" readonly aria-label="邀请链接" @focus="$event.target.select()">
      <p class="invite-help">邀请 10 分钟内可领取。<br><strong>加入后的游戏身份有效 24 小时。</strong><br>链接到期不会中断已加入玩家。</p>
     </template>
     <template v-else><div class="match-summary" :style="{'--map-accent':map.color}"><span>即将前往</span><strong>{{map.name}}</strong><small>{{map.english}}</small><div>1 <em>VS</em> 1</div><p>同角色可选<br>蓝方与红方区分彼此</p></div></template>
     <button v-if="room.phase==='lobby'" class="room-ready" :class="{confirmed:me?.ready}" :disabled="!editable||!me?.online" @click="command('ready',{ready:!me?.ready})">{{me?.ready?'已准备 · 点击取消':'我准备好了'}}</button>
     <button v-if="host&&room.phase==='lobby'" class="room-start" :disabled="!canStart||busy" @click="command('start')">{{canStart?'开始对战 →':'等待双方准备'}}</button>
     <div v-if="['loading','countdown','reconnecting'].includes(room.phase)" class="room-loading"><span class="loading-orbit"/><strong v-if="room.phase==='countdown'">{{seconds}}</strong>{{room.phase==='countdown'?'即将开战':room.phase==='reconnecting'?'重连中…':'正在准备战场…'}}</div>
     <button v-if="host&&players.length===2&&room.phase==='lobby'" class="room-remove" :disabled="busy" @click="command('kick')">移除好友，重新邀请</button>
    </aside>
   </div>
   <p v-if="error||status?.error" class="room-error" role="alert">{{error||status.error}}</p>
   <footer class="room-footer"><span>PRIVATE ROOM / 仅邀请加入</span><span>{{status?.ping?`${status.ping} ms`:'建立安全连接'}} · {{host?'你是蓝方':'你是红方'}}</span></footer>
  </div>
 </section>
</template>

<style scoped>
