spacing:.4em;color:#9db8bb}.seat-name{display:flex;align-items:center;justify-content:space-between;gap:8px}.seat-name h2{font-size:17px;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin:8px 0 16px}.seat-name h2 small{font-size:10px;margin-left:8px;font-weight:400;color:#a4bcbc}.seat-name>b{font-size:10px;white-space:nowrap;color:#91a9ad}.seat-name>b.ready{color:#bae3b8}.seat-characters{display:flex;gap:6px}.seat-characters button{flex:1;background:#0a222a6b;border:1px solid #c5ded227;border-radius:7px;color:#a8c0c5;padding:9px 3px;font-size:11px}.seat-characters button.selected{border-color:#d8c296b0;background:#cdb98a1a;color:#f3dcaf}.seat-character-label{font-size:11px;color:#a8c0c5;margin:10px 0}.empty-seat{display:flex;flex-direction:column;align-items:center;justify-content:center;border:1px dashed #aec9c84a;background:#93bab408;min-height:269px;text-align:center}.empty-plus{font-size:36px;color:#a6c5c44d}.empty-seat h2{font-size:17px;margin:12px 0 0}.empty-seat p{font-size:12px;line-height:1.8;color:#88a5ab}.waiting-dots{font-size:6px;letter-spacing:8px;color:#d1b98790;margin-top:12px}.room-maps{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.room-maps button{min-height:103px;padding:13px 10px;text-align:left;border:1px solid #b4d0d01f;border-radius:10px;background:linear-gradient(145deg,color-mix(in srgb,var(--map-accent) 10%,#203239),#14282f);color:#c9d2cd;position:relative}.room-maps button.selected{border-color:var(--map-accent);box-shadow:inset 0 -3px var(--map-accent)}.room-maps button>span{color:var(--map-accent);font-size:10px}.room-maps strong,.room-maps small{display:block}.room-maps strong{font-size:13px;margin:10px 0 5px}.room-maps small{font-size:8px;letter-spacing:.08em;color:#8da6ab}.room-rules{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:22px;font-size:11px;color:#9bb4b8}.room-rules strong{font-size:12px;color:#e5d8ba;font-weight:500}.room-rules i{height:3px;width:3px;border-radius:50%;background:#6b8a8d}.room-notice{font-size:11px;line-height:1.8;color:#8eaaaf;margin:16px 0 0}.room-aside{padding:22px;background:#0b222869;border:1px solid #b4cccc24;border-radius:16px}.qr-frame{aspect-ratio:1;border-radius:12px;overflow:hidden;background:#fff7e9;display:grid;place-items:center}.qr-frame img{width:100%;height:100%;image-rendering:pixelated}.qr-placeholder{color:#42616a;text-align:center;font-size:12px;padding:15px}.invite-expiry{display:flex;justify-content:space-between;align-items:center;font-size:10px;margin-top:12px;color:#d4c39d}.invite-expiry button{font-size:10px;border:0;color:#9ab6be;background:transparent;padding:4px;cursor:pointer}.expired{color:#afbec0}.room-copy,.room-ready,.room-start{width:100%;border-radius:9px;padding:13px;font-size:13px;font-weight:600;cursor:pointer}.room-copy{margin-top:12px;border:1px solid #d5c29b66;background:#d0b98a14;color:#e8d5ad}.invite-link{display:block;width:100%;margin-top:9px;padding:7px;color:#9ab4b9;background:#0c252e;border:1px solid #aacaca22;border-radius:5px;font-size:10px}.invite-help{font-size:10px;line-height:1.9;color:#8da7ad;margin:15px 0 20px}.invite-help strong{font-weight:500;color:#c4d4cb}.room-ready{margin-top:12px;border:1px solid #dac69e73;background:transparent;color:#ecdcbb}.room-ready.confirmed{border-color:#a6d9b17a;color:#bcdfbc;background:#82bd8c17}.room-start{margin-top:10px;background:#edcd94;border:1px solid #edcd94;color:#172b32}.room-start:disabled{background:#29424a;color:#80999e;border-color:#7996972a}.room-remove{border:0;background:transparent;color:#a7a59b;font-size:10px;padding:16px 0 0;width:100%}.match-summary{padding:28px 0;text-align:center;background:radial-gradient(circle,color-mix(in srgb,var(--map-accent) 12%,transparent),transparent 75%)}.match-summary>span{font-size:10px;letter-spacing:.2em;color:#adc0bd}.match-summary>strong{display:block;font-size:24px;margin:12px 0;color:var(--map-accent)}.match-summary>small{font-size:8px;letter-spacing:.14em;color:#99b0b4}.match-summary>div{font-size:52px;font-weight:800;margin:35px 0;color:#dfd3b6}.match-summary em{font-size:15px;vertical-align:middle;margin:0 12px;color:#90a9ad;font-style:normal}.match-summary p{font-size:11px;line-height:1.8;color:#91adb1}.room-loading{display:flex;justify-content:center;align-items:center;gap:10px;color:#d5c398;font-size:12px;margin:20px 0}.loading-orbit{width:16px;height:16px;border:2px solid #c3d1bf25;border-top-color:#d5c398;border-radius:50%;animation:orbit 1s linear infinite}@keyframes orbit{to{transform:rotate(360deg)}}.room-error{background:#b8493521;border:1px solid #dd9a7650;color:#ffcab0;font-size:12px;padding:13px 16px;border-radius:9px}.room-footer{display:flex;justify-content:space-between;gap:12px;color:#65878e;font-size:9px;letter-spacing:.08em;padding-top:24px}button:disabled{cursor:default;opacity:.6}button:focus-visible,input:focus-visible{outline:2px solid #f2d8a4;outline-offset:3px}
